/** Poll until the designated responder commits, or the wait expires. */
export async function waitForCommittedTurn(
  client: DoorClient,
  submitted: SubmitTurnResult,
  timeoutMs = COMMITTED_REPLY_TIMEOUT_MS,
  signal?: AbortSignal,
): Promise<CommittedTurn> {
  const deadline = Date.now() + timeoutMs;
  let delay = POLL_MS;
  while (Date.now() < deadline) {
    if (signal?.aborted) throw new Error("Response wait cancelled; outcome is unknown.");
    const turn = await getTurnResponse(client, submitted.turn_id);
    if (turn) {
      if (
        turn.conversation_id !== submitted.conversation_id ||
        turn.turn_id !== submitted.turn_id ||
        turn.turn_index !== submitted.turn_index
      ) {
        throw new Error("Committed response does not match the submitted human turn.");
      }
      return turn;
    }
    const remaining = deadline - Date.now();
    if (remaining <= 0) break;
    await sleep(Math.min(delay, remaining), signal);
    delay = Math.min(delay * 2, 4_000);
  }
  throw new Error("Response wait expired; generation or commit outcome is unknown.");
}


